protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // Create a map from vertex to its incident edges in the tour
    Map<V, Set<E>> vertexToEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexToEdges.computeIfAbsent(source, k -> new HashSet<>()).add(edge);
        vertexToEdges.computeIfAbsent(target, k -> new HashSet<>()).add(edge);
    }

    // Find a starting vertex (any vertex with degree 2 in the tour)
    V current = null;
    for (V vertex : vertexToEdges.keySet()) {
        if (vertexToEdges.get(vertex).size() == 2) {
            current = vertex;
            break;
        }
    }

    if (current == null) {
        // If no vertex with degree 2 is found, the tour might be invalid or empty
        return new GraphPath<>(Collections.emptyList(), Collections.emptyList());
    }

    // Build the path by traversing the tour
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();

    vertices.add(current);
    while (true) {
        Set<E> incidentEdges = vertexToEdges.get(current);
        E nextEdge = null;
        for (E edge : incidentEdges) {
            if (!usedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        usedEdges.add(nextEdge);
        edges.add(nextEdge);

        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        vertices.add(nextVertex);
        current = nextVertex;

        // Stop if we've returned to the start and used all edges
        if (current.equals(vertices.get(0)) && usedEdges.size() == tour.size()) {
            break;
        }
    }

    return new GraphPath<>(vertices, edges);
}

